import{_ as a,o as t,c as s,a4 as i}from"./chunks/framework.DpieW3qv.js";const u=JSON.parse('{"title":"FAQ","description":"","frontmatter":{"title":"FAQ"},"headers":[],"relativePath":"troubleshooting/faq.md","filePath":"troubleshooting/faq.md","lastUpdated":null}'),o={name:"troubleshooting/faq.md"};function r(n,e,d,l,h,c){return t(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="frequently-asked-questions" tabindex="-1">Frequently Asked Questions <a class="header-anchor" href="#frequently-asked-questions" aria-label="Permalink to &quot;Frequently Asked Questions&quot;">​</a></h1><h2 id="general" tabindex="-1">General <a class="header-anchor" href="#general" aria-label="Permalink to &quot;General&quot;">​</a></h2><h3 id="what-does-this-tool-do" tabindex="-1">What does this tool do? <a class="header-anchor" href="#what-does-this-tool-do" aria-label="Permalink to &quot;What does this tool do?&quot;">​</a></h3><p>Transforms Smartsheet or Excel wireframes into production-ready SFCC content:</p><ul><li>Fetches data from Smartsheet or Excel</li><li>Generates HTML from templates</li><li>Syncs to SFCC via OCAPI</li><li>Manages asset versions</li></ul><h3 id="how-much-time-does-it-save" tabindex="-1">How much time does it save? <a class="header-anchor" href="#how-much-time-does-it-save" aria-label="Permalink to &quot;How much time does it save?&quot;">​</a></h3><p>Typical refresh: 2-4 hours → 15 minutes (85% reduction)</p><h2 id="workflow" tabindex="-1">Workflow <a class="header-anchor" href="#workflow" aria-label="Permalink to &quot;Workflow&quot;">​</a></h2><h3 id="what-s-the-difference-between-pull-and-build" tabindex="-1">What&#39;s the difference between <code>pull</code> and <code>build</code>? <a class="header-anchor" href="#what-s-the-difference-between-pull-and-build" aria-label="Permalink to &quot;What&#39;s the difference between `pull` and `build`?&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Command</th><th>What It Does</th><th>Input</th><th>Output</th></tr></thead><tbody><tr><td><code>make pull</code></td><td>Git sync + fetch data + dashboard</td><td>Smartsheet/Excel</td><td>refresh.json</td></tr><tr><td><code>make build</code></td><td>Generate HTML + OCAPI payload</td><td>refresh.json</td><td>HTML + JSON + ocapi-payload.json</td></tr></tbody></table><p><code>pull</code> gets the data and shows you what&#39;s available; <code>build</code> processes a specific date.</p><h3 id="why-did-make-build-skip-my-date" tabindex="-1">Why did <code>make build</code> skip my date? <a class="header-anchor" href="#why-did-make-build-skip-my-date" aria-label="Permalink to &quot;Why did `make build` skip my date?&quot;">​</a></h3><p><strong>Build guards</strong> prevent accidental overwrites:</p><ul><li><strong>&quot;Already synced&quot;</strong> — someone already pushed this date to SFCC. Use <code>make build FORCE=1</code> to force rebuild, or <code>make status</code> to pick a different refresh.</li><li><strong>&quot;Already built&quot;</strong> — HTML and payload already exist. Use <code>make push</code> to sync, or <code>make build</code> (then save a template/config to rebuild) or <code>make build FORCE=1</code> to force rebuild.</li></ul><h3 id="can-i-process-multiple-dates-at-once" tabindex="-1">Can I process multiple dates at once? <a class="header-anchor" href="#can-i-process-multiple-dates-at-once" aria-label="Permalink to &quot;Can I process multiple dates at once?&quot;">​</a></h3><p>Producers work one date at a time via <code>make status</code> + <code>make build</code>. This is by design — build guards prevent accidental overwrites across dates. Developers can run <code>make test-brands</code> to verify both brands E2E from a clean dev-env. To build every date in batch, use <code>make build-all</code> (after <code>make pull</code>).</p><h3 id="how-do-i-preview-changes-before-syncing" tabindex="-1">How do I preview changes before syncing? <a class="header-anchor" href="#how-do-i-preview-changes-before-syncing" aria-label="Permalink to &quot;How do I preview changes before syncing?&quot;">​</a></h3><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> preview</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Uses your selected date. Shows preview links in the output.</p><h3 id="what-if-i-need-to-edit-content-after-generating" tabindex="-1">What if I need to edit content after generating? <a class="header-anchor" href="#what-if-i-need-to-edit-content-after-generating" aria-label="Permalink to &quot;What if I need to edit content after generating?&quot;">​</a></h3><p>Edit files in <code>dev-env/{brand}/refreshes/{date}/r#/</code>:</p><ul><li><strong>HTML</strong>: <code>preview/templates/{assetType}/*.html</code></li><li><strong>JSON</strong>: <code>assets/*.json</code></li></ul><p>Then rebuild:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> FORCE=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Uses your sticky date. No need for <code>DATE=</code>.</p><h3 id="will-my-custom-html-get-overwritten" tabindex="-1">Will my custom HTML get overwritten? <a class="header-anchor" href="#will-my-custom-html-get-overwritten" aria-label="Permalink to &quot;Will my custom HTML get overwritten?&quot;">​</a></h3><p>No. Assets in <code>DEVELOPER</code> mode preserve custom HTML across fetches. Only <code>TEMPLATE</code> mode assets regenerate.</p><p>See <a href="/ocapi-docs.github.io/config/slots.html#mode-types">Asset Modes</a>.</p><h3 id="what-if-another-producer-already-built-my-date" tabindex="-1">What if another producer already built my date? <a class="header-anchor" href="#what-if-another-producer-already-built-my-date" aria-label="Permalink to &quot;What if another producer already built my date?&quot;">​</a></h3><p>The build guard will tell you. Run <code>make pull</code> to get their latest work, then <code>make status</code> to see the full board and pick a different refresh (or <code>make status DATE=...</code>).</p><p>See <a href="/ocapi-docs.github.io/guides/multi-producer.html">Multi-Producer Guide</a>.</p><h2 id="sfcc-integration" tabindex="-1">SFCC Integration <a class="header-anchor" href="#sfcc-integration" aria-label="Permalink to &quot;SFCC Integration&quot;">​</a></h2><h3 id="how-do-i-check-if-sfcc-connection-is-working" tabindex="-1">How do I check if SFCC connection is working? <a class="header-anchor" href="#how-do-i-check-if-sfcc-connection-is-working" aria-label="Permalink to &quot;How do I check if SFCC connection is working?&quot;">​</a></h3><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> health</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="what-credentials-do-i-need" tabindex="-1">What credentials do I need? <a class="header-anchor" href="#what-credentials-do-i-need" aria-label="Permalink to &quot;What credentials do I need?&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Variable</th><th>Description</th></tr></thead><tbody><tr><td><code>SFCC_BASE_URL</code></td><td>Instance URL</td></tr><tr><td><code>SFCC_CLIENT_ID</code></td><td>OAuth client ID</td></tr><tr><td><code>SFCC_CLIENT_SECRET</code></td><td>OAuth client secret</td></tr><tr><td><code>SFCC_SITE_ID</code></td><td>Site identifier</td></tr><tr><td><code>SFCC_LIBRARY_ID</code></td><td>Content library ID</td></tr><tr><td><code>AUTH_URL</code></td><td>OAuth token endpoint</td></tr></tbody></table><p>See <a href="/ocapi-docs.github.io/guides/env-and-auth.html">Environment Setup</a>.</p><h3 id="can-i-sync-to-production-directly" tabindex="-1">Can I sync to production directly? <a class="header-anchor" href="#can-i-sync-to-production-directly" aria-label="Permalink to &quot;Can I sync to production directly?&quot;">​</a></h3><p>No. The workflow is:</p><ol><li><code>make push</code> → Validates data quality + syncs to <strong>staging</strong></li><li><code>make replicate</code> → Opens manual replication checklist for <strong>production</strong></li></ol><p>This prevents accidental production pushes.</p><h3 id="how-do-i-delete-content-from-sfcc" tabindex="-1">How do I delete content from SFCC? <a class="header-anchor" href="#how-do-i-delete-content-from-sfcc" aria-label="Permalink to &quot;How do I delete content from SFCC?&quot;">​</a></h3><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> delete</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> DATE=2026-02-03</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Or manually in Business Manager.</p><h2 id="templates" tabindex="-1">Templates <a class="header-anchor" href="#templates" aria-label="Permalink to &quot;Templates&quot;">​</a></h2><h3 id="where-are-templates-located" tabindex="-1">Where are templates located? <a class="header-anchor" href="#where-are-templates-located" aria-label="Permalink to &quot;Where are templates located?&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>templates/</span></span>\n<span class="line"><span>├── homepage/</span></span>\n<span class="line"><span>│   ├── template.html</span></span>\n<span class="line"><span>│   └── zones/*.html</span></span>\n<span class="line"><span>├── pph/</span></span>\n<span class="line"><span>│   └── template.html</span></span>\n<span class="line"><span>└── ...</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><h3 id="how-do-i-validate-templates" tabindex="-1">How do I validate templates? <a class="header-anchor" href="#how-do-i-validate-templates" aria-label="Permalink to &quot;How do I validate templates?&quot;">​</a></h3><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="what-template-engine-is-used" tabindex="-1">What template engine is used? <a class="header-anchor" href="#what-template-engine-is-used" aria-label="Permalink to &quot;What template engine is used?&quot;">​</a></h3><p>Handlebars. See <a href="/ocapi-docs.github.io/guides/templates.html">Template Authoring</a>.</p><h2 id="data" tabindex="-1">Data <a class="header-anchor" href="#data" aria-label="Permalink to &quot;Data&quot;">​</a></h2><h3 id="where-does-data-come-from" tabindex="-1">Where does data come from? <a class="header-anchor" href="#where-does-data-come-from" aria-label="Permalink to &quot;Where does data come from?&quot;">​</a></h3><p>Smartsheet wireframe, managed by the Ecomm team.</p><h3 id="can-i-use-excel-instead" tabindex="-1">Can I use Excel instead? <a class="header-anchor" href="#can-i-use-excel-instead" aria-label="Permalink to &quot;Can I use Excel instead?&quot;">​</a></h3><p>Yes. Place your Excel file in <code>docs/excel/</code> and run:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> FILE=path/to/wireframe.xlsx</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="how-do-i-see-what-data-was-fetched" tabindex="-1">How do I see what data was fetched? <a class="header-anchor" href="#how-do-i-see-what-data-was-fetched" aria-label="Permalink to &quot;How do I see what data was fetched?&quot;">​</a></h3><p>Check <code>dev-env/{brand}/refreshes/{date}/r#/refresh.json</code></p><h2 id="status-and-dev-env" tabindex="-1">Status and dev-env <a class="header-anchor" href="#status-and-dev-env" aria-label="Permalink to &quot;Status and dev-env&quot;">​</a></h2><h3 id="why-does-status-show-buildready-for-refreshes-ive-already-pushed" tabindex="-1">Why does status show BUILD/READY for refreshes I&#39;ve already pushed? <a class="header-anchor" href="#why-does-status-show-buildready-for-refreshes-ive-already-pushed" aria-label="Permalink to &quot;Why does status show BUILD/READY for refreshes I&#39;ve already pushed? {#why-does-status-show-buildready-for-refreshes-ive-already-pushed}&quot;">​</a></h3><p><strong>LIVE</strong> and <strong>SYNCED</strong> come from two places:</p><ol><li><strong>Local state</strong> in <code>dev-env</code>: each refresh has <code>sync-config.json</code> in <code>dev-env/{brand}/refreshes/{date}/r#/</code>. After a successful <code>make push</code>, that file is updated with <code>synced: true</code>.</li><li><strong>SFCC (when OCAPI is enabled):</strong> when you run <code>make status</code>, the CLI also checks SFCC for each refresh’s campaign (e.g. <code>loft-2026-02-12-r1</code>). If the campaign exists on the site, that refresh is shown as <strong>SYNCED</strong> (or <strong>LIVE</strong> if it’s today’s date), even when local sync state is missing (e.g. after you deleted <code>dev-env</code>).</li></ol><p>So status is <strong>tied to both local and SFCC</strong>: local sync state is used first; when OCAPI is enabled, any refresh whose campaign exists on SFCC is treated as SYNCED/LIVE. After a dev-env wipe, <code>make status</code> can still show accurate SYNCED/LIVE for pushed refreshes as long as OCAPI is configured and the CLI can reach SFCC.</p><p><strong>If you don’t use OCAPI or SFCC is unreachable:</strong> status falls back to local-only. Deleting <code>dev-env</code> then means you’ll see BUILD/READY for everything until you re-push or re-enable SFCC.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><h3 id="asset-not-found-error" tabindex="-1">&quot;Asset not found&quot; error <a class="header-anchor" href="#asset-not-found-error" aria-label="Permalink to &quot;&quot;Asset not found&quot; error&quot;">​</a></h3><p>The asset doesn&#39;t exist in SFCC yet. Check:</p><ol><li>Was the action set to <code>LAUNCH</code>?</li><li>Did the initial sync succeed?</li></ol><h3 id="campaign-already-exists-error" tabindex="-1">&quot;Campaign already exists&quot; error <a class="header-anchor" href="#campaign-already-exists-error" aria-label="Permalink to &quot;&quot;Campaign already exists&quot; error&quot;">​</a></h3><p>A campaign with the same ID already exists. Either:</p><ol><li>Use <code>UPDATE</code> action instead of <code>LAUNCH</code></li><li>Delete the existing campaign first</li></ol><h3 id="authentication-failed-error" tabindex="-1">&quot;Authentication failed&quot; error <a class="header-anchor" href="#authentication-failed-error" aria-label="Permalink to &quot;&quot;Authentication failed&quot; error&quot;">​</a></h3><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> health</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Check your <code>.env</code> credentials.</p><h3 id="rate-limited-error" tabindex="-1">&quot;Rate limited&quot; error <a class="header-anchor" href="#rate-limited-error" aria-label="Permalink to &quot;&quot;Rate limited&quot; error&quot;">​</a></h3><p>The API is throttling requests. The client retries automatically, but if it persists:</p><ol><li>Wait a few minutes</li><li>Reduce batch size</li><li>Check for other processes hitting the API</li></ol><h3 id="template-not-found" tabindex="-1">Template not found <a class="header-anchor" href="#template-not-found" aria-label="Permalink to &quot;Template not found&quot;">​</a></h3><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Ensure the template file exists in <code>templates/{assetType}/template.html</code>.</p><h3 id="empty-preview" tabindex="-1">Empty preview <a class="header-anchor" href="#empty-preview" aria-label="Permalink to &quot;Empty preview&quot;">​</a></h3><p>Check if:</p><ol><li><code>refresh.json</code> has content</li><li>Template exists for the asset type</li><li>No validation errors</li></ol><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h2 id="performance" tabindex="-1">Performance <a class="header-anchor" href="#performance" aria-label="Permalink to &quot;Performance&quot;">​</a></h2><h3 id="how-long-does-a-sync-take" tabindex="-1">How long does a sync take? <a class="header-anchor" href="#how-long-does-a-sync-take" aria-label="Permalink to &quot;How long does a sync take?&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Operation</th><th>Time</th></tr></thead><tbody><tr><td>Fetch</td><td>5-10 seconds</td></tr><tr><td>Generate</td><td>2-5 seconds per refresh</td></tr><tr><td>Sync</td><td>1-2 minutes (depends on asset count)</td></tr><tr><td>Replicate</td><td>2-5 minutes</td></tr></tbody></table><h3 id="can-i-speed-up-syncing" tabindex="-1">Can I speed up syncing? <a class="header-anchor" href="#can-i-speed-up-syncing" aria-label="Permalink to &quot;Can I speed up syncing?&quot;">​</a></h3><p>The API client uses batch operations and rate limiting. Speed is mostly limited by SFCC API response times.</p><h2 id="registry" tabindex="-1">Registry <a class="header-anchor" href="#registry" aria-label="Permalink to &quot;Registry&quot;">​</a></h2><h3 id="where-did-make-registry-and-make-registry-ipids-go" tabindex="-1">Where did <code>make registry</code> and <code>make registry-ipids</code> go? <a class="header-anchor" href="#where-did-make-registry-and-make-registry-ipids-go" aria-label="Permalink to &quot;Where did `make registry` and `make registry-ipids` go?&quot;">​</a></h3><p>They’re still there:</p><ul><li><strong><code>make registry</code></strong> — Shows the live asset registry (zones and item counts). Uses <code>dev-env/{brand}/asset-registry.json</code>.</li><li><strong><code>make registry-ipids</code></strong> — Lists all IPIDs in the registry (asset type, zone, order, IPID).</li></ul><p>Both read from <strong>dev-env</strong>. If you’ve deleted or reset <code>dev-env</code>, the registry file is gone so <code>make registry</code> will show “(empty)” and <code>make registry-ipids</code> will list no IPIDs. Run <strong><code>make registry &lt;brand&gt; --bootstrap</code></strong> to repopulate the registry from existing refresh folders (this only uses local data; it does not fetch from SFCC). See <a href="/ocapi-docs.github.io/cli/registry.html">Registry</a>.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/ocapi-docs.github.io/reference/commands.html">Commands Reference</a></li><li><a href="/ocapi-docs.github.io/troubleshooting/common-errors.html">Troubleshooting Guide</a></li><li><a href="/ocapi-docs.github.io/guides/quick-start.html">Quick Start</a></li><li><a href="/ocapi-docs.github.io/cli/registry.html">Registry</a></li></ul>',97)])])}const m=a(o,[["render",r]]);export{u as __pageData,m as default};
